mapper.select:
SELECT 
FROM tb_outbound_order t
WHERE t.row_valid = 1
AND t.source_system = #{sourceSystem}
AND t.request_id = #{requestId}
LIMIT 1

SELECT 
FROM tb_outbound_order t
WHERE t.row_valid = 1
AND t.source_system = #{sourceSystem}
AND t.source_order_num = #{sourceOrderNum}
LIMIT 1

SELECT 
FROM tb_outbound_order t
WHERE t.row_valid = 1

    AND t.order_num = #{orderNum}


    AND t.source_system = #{sourceSystem}


    AND t.source_order_num = #{sourceOrderNum}


    AND t.warehouse_code = #{warehouseCode}


    AND t.state = #{state}


    AND date_format(t.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


    AND date_format(t.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')

ORDER BY t.id DESC
